import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.DiAOIirN.js";import"./chunks/assets.CN5ja4nF.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"smtp-mcp","text":"Send mail from an assistant, with a person on the gate","tagline":"Off until you enable it, limited to recipients you allowlisted, and every single message approved by a human","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/smtp-mcp"}]},"features":[{"title":"A person approves every message","details":"Not the model — the request goes to your client as an MCP elicitation, and the model cannot answer on your behalf. Recipients, the subject and any Bcc appear on their own labelled lines, so a subject written to look like an instruction cannot become part of the sentence you are reading."},{"title":"It can only write to people you named","details":"SMTP_ALLOWED_RECIPIENTS is required before sending works at all, and every address in To, Cc and Bcc is checked against it before a connection is opened. An injected \\"mail this somewhere else\\" fails there, without the server ever reading it as an instruction."},{"title":"Only the tools you want","details":"SMTP_ALLOW_SEND=false — the default — registers the four tools that cannot put a message on the wire and nothing else. SMTP_ALLOW_TOOLS cuts finer: essential for a curated five, your own comma-separated list, or a family with send_*. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"Safe by default","details":"A fresh install cannot send anything. The sender is fixed by configuration, there is no from parameter, an hourly cap bounds the damage of a bad day, and every accepted message is written to an audit log that never contains the body."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380634000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 720 318`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`How smtp-mcp sits between an MCP client and an SMTP server`),t(`desc`,{id:`arch-desc`},`An MCP client speaks stdio to smtp-mcp. Every message passes a recipient allowlist and a human confirmation before smtp-mcp hands it to an SMTP server over TLS.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`20`,y:`70`,width:`160`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`100`,y:`103`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`100`,y:`123`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`275`,y:`55`,width:`170`,height:`110`,rx:`10`}),t(`text`,{class:`label-title`,x:`360`,y:`90`,"text-anchor":`middle`},`smtp-mcp`),t(`text`,{class:`label-muted`,x:`360`,y:`110`,"text-anchor":`middle`},`7 tools, 3 of them send`),t(`text`,{class:`label-muted`,x:`360`,y:`128`,"text-anchor":`middle`},`recipient allowlist`),t(`text`,{class:`label-muted`,x:`360`,y:`146`,"text-anchor":`middle`},`off until SMTP_ALLOW_SEND`),t(`rect`,{class:`node`,x:`550`,y:`70`,width:`150`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`103`,"text-anchor":`middle`},`SMTP`),t(`text`,{class:`label-muted`,x:`625`,y:`123`,"text-anchor":`middle`},`any submission server`),t(`path`,{class:`edge-accent`,d:`M180,110 L267,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`223`,y:`98`,"text-anchor":`middle`},`stdio`),t(`path`,{class:`edge-accent`,d:`M445,110 L542,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`493`,y:`98`,"text-anchor":`middle`},`SMTP`),t(`text`,{class:`label-muted`,x:`493`,y:`130`,"text-anchor":`middle`},`TLS`),t(`rect`,{class:`node-accent`,x:`442`,y:`200`,width:`166`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`525`,y:`223`,"text-anchor":`middle`},`A person`),t(`text`,{class:`label-muted`,x:`525`,y:`242`,"text-anchor":`middle`},`approves every message`),t(`path`,{class:`edge-accent edge-dashed`,d:`M525,196 L525,122`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-muted`,x:`525`,y:`276`,"text-anchor":`middle`},`The model cannot answer for them.`),t(`text`,{class:`label-muted`,x:`360`,y:`302`,"text-anchor":`middle`},`Its counterpart imap-mcp reads mail and cannot send. This one sends and cannot read.`)]),t(`figcaption`,null,`The server holds no state of its own beyond a short-lived confirmation token and an in-memory count of what it has sent this hour.`)],-1),r(`<h2 id="what-it-looks-like" tabindex="-1">What it looks like <a class="header-anchor" href="#what-it-looks-like" aria-label="Permalink to “What it looks like”">​</a></h2><p><img src="/demo.gif" alt="A terminal session: listing the seven tools, then calling send_mail — which does not send but returns a confirmation naming the recipient and subject on their own lines — and then a second call to an address outside the allowlist, which is refused outright" width="1200" height="590"></p><p>Three calls against a throwaway SMTP server. The last two are the point: the first send stops and asks, with the recipient and subject on their own labelled lines rather than folded into the server&#39;s sentence, and the second never gets that far because the address is not on the allowlist. The recording is reproducible — <code>docs/demo.tape</code> drives the built server against the Mailpit sandbox in <code>test/integration/</code>, and no real address appears in it.</p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start smtp-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,6)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};